parameters.jsCode:
// Turn a pile of multi-run logs into the smallest evidence block that can still
// prove a pattern, and count everything the model must not be asked to count.
//
// This node exists because of one number: Groq's free tier allows 8,000 tokens
// per minute, and that ceiling is on INPUT. A single Playwright failure log is
// bigger than the whole per-minute allowance, so the logs cannot simply be
// forwarded. Choosing which lines matter is code's job, not the prompt's.
//
// It also does all the arithmetic. Flakiness is a frequency claim, and models
// are unreliable at counting - so runs, failures and the rate are computed here
// and the model is only asked to explain the pattern.

// ~3k tokens at ~4 chars/token. The rest of the 8,000/minute ceiling goes on
// the system message (~1.1k), the schema the parser injects (~0.4k) and the
// answer. The answer needs far more room than it looks: gpt-oss reasons before
// it replies, that reasoning is billed as completion, and n8n's Groq node has
// no reasoning_effort setting to turn it down - so the budget below is what is
// left after leaving ~3k for it.
const CHAR_BUDGET = 12000;
const MIN_PER_RUN = 350;
const CONTEXT_LINES = 3;
const MAX_FAILING_SHOWN = 12;

// Lines worth keeping. A 4,000 line log usually has about 20 of them.
const SIGNAL = /(error|exception|timeout|timed out|econnre|econnrefused|etimedout|refused|unreachable|stale|not found|no such element|assert|expect(ed)?|actual|received|fail(ed|ure)?|retry|retrying|flake|panic|fatal|traceback|unhandled|at [A-Za-z0-9_$.]+\()/i;
const PASS_WORD = /(pass|success|ok\b|green|completed)/i;
const FAIL_WORD = /(fail|error|broken|timed_out|timeout|cancel|red)/i;

const hook = $('Flaky Test Webhook').first().json;
const body = (hook && hook.body) || hook || {};
const testName = String(body.test_name || 'Unnamed test').trim();

// Runs arrive one of two ways: inline on the webhook, or fetched by the HTTP
// node from whatever CI is in use. Inline wins - it is what makes this
// workflow runnable without a CI attached.
function pickRuns(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload;
  for (const key of ['runs', 'items', 'data', 'results', 'workflow_runs', 'builds', 'executions']) {
    if (Array.isArray(payload[key])) return payload[key];
  }
  if (payload.log || payload.logs || payload.output || payload.stdout) return [payload];
  return [];
}

let source = 'inline';
let raw = pickRuns(body.runs);
if (!raw.length) {
  source = 'fetched';
  let fetched = null;
  try { fetched = $input.first().json; } catch (e) { fetched = null; }
  raw = pickRuns(fetched);
}

function normalize(run, i) {
  const log = String(
    run.log ?? run.logs ?? run.output ?? run.stdout ?? run.stderr ?? run.message ?? run.body ?? ''
  );
  const statusRaw = String(run.status ?? run.conclusion ?? run.result ?? run.outcome ?? '').trim();
  let status;
  if (PASS_WORD.test(statusRaw)) status = 'passed';
  else if (FAIL_WORD.test(statusRaw)) status = 'failed';
  else status = log && SIGNAL.test(log) ? 'failed' : 'unknown';

  return {
    run_id: String(run.run_id ?? run.id ?? run.number ?? run.build ?? 'run-' + (i + 1)),
    status,
    started_at: String(run.started_at ?? run.created_at ?? run.timestamp ?? run.date ?? ''),
    duration_ms: Number(run.duration_ms ?? run.duration ?? 0) || 0,
    log,
  };
}

// Keep the lines around every signal hit rather than a blind tail - the useful
// part of a long log is rarely at the end.
function failureRegion(log, budget) {
  const lines = String(log).split(/\r?\n/);
  const keep = new Set();
  lines.forEach((line, i) => {
    if (SIGNAL.test(line)) {
      for (let j = Math.max(0, i - CONTEXT_LINES); j <= Math.min(lines.length - 1, i + CONTEXT_LINES); j++) {
        keep.add(j);
      }
    }
  });

  let picked = Array.from(keep).sort((a, b) => a - b);
  let matched = picked.length > 0;
  if (!matched) picked = lines.map((_, i) => i).slice(-20); // nothing matched: the tail is next best

  const out = [];
  let used = 0;
  let prev = -1;
  let clipped = false;
  for (const i of picked) {
    if (prev !== -1 && i > prev + 1) { out.push('...'); used += 4; }
    const line = String(lines[i]).trim();
    if (!line) { prev = i; continue; }
    if (used + line.length + 1 > budget) { out.push('... [truncated to fit the token budget]'); clipped = true; break; }
    out.push(line);
    used += line.length + 1;
    prev = i;
  }
  return { text: out.join('\n'), clipped, matched };
}

// Collapse a line into something comparable across runs: no numbers, no paths,
// no hex, no timestamps. Two runs failing "after 30012ms" and "after 30004ms"
// have to land on the same signature or nothing clusters.
function signature(line) {
  return String(line)
    .replace(/\d{4}-\d{2}-\d{2}[T ][\d:.,]+Z?/g, '<ts>')
    .replace(/0x[0-9a-fA-F]+/g, '<hex>')
    .replace(/[A-Za-z]:\\[^\s:]+/g, '<path>')
    .replace(/\/[\w./-]+\.(js|ts|py|java|rb|go|cs)\b/g, '<path>')
    .replace(/\b\d+(\.\d+)?\s*(ms|s|sec|seconds|minutes)?\b/gi, '<n>')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 120);
}

// Pick the line the run actually failed on, not merely the first interesting
// one. Taking the first match keys the signature on whatever noise came
// earliest - a DEBUG "retrying request" line - so two runs that died on the
// identical timeout end up in different buckets and no pattern clusters.
const SEVERE = /(^\s*(Error|Exception|AssertionError|FATAL|PANIC)\b|Timeout \d+\s*ms exceeded|ECONNRESET|ECONNREFUSED|ETIMEDOUT|StaleElement|NoSuchElement)/i;
const MODERATE = /(assert|expect(ed)?:|received:|fail(ed|ure))/i;

function topSignalLine(log) {
  const lines = String(log).split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  return (
    lines.find((l) => SEVERE.test(l)) ||
    lines.find((l) => MODERATE.test(l)) ||
    lines.find((l) => SIGNAL.test(l)) ||
    ''
  );
}

const runs = raw.map(normalize);
const failing = runs.filter((r) => r.status === 'failed');
const passing = runs.filter((r) => r.status === 'passed');
const unknown = runs.filter((r) => r.status === 'unknown');

const shown = failing.slice(0, MAX_FAILING_SHOWN);
const perRun = Math.max(MIN_PER_RUN, Math.floor(CHAR_BUDGET / Math.max(1, shown.length)));

let anyClipped = shown.length < failing.length;
const blocks = shown.map((run) => {
  const region = failureRegion(run.log, perRun);
  if (region.clipped) anyClipped = true;
  const when = run.started_at ? ' at ' + run.started_at : '';
  const dur = run.duration_ms ? ' after ' + run.duration_ms + 'ms' : '';
  return 'RUN ' + run.run_id + ' (failed' + dur + when + ')\n' + (region.text || '(no log captured for this run)');
});

// Count in code. The model is told these numbers, never asked for them.
const tally = {};
failing.forEach((run) => {
  const sig = signature(topSignalLine(run.log));
  if (!sig) return;
  tally[sig] = (tally[sig] || 0) + 1;
});
const signature_tally = Object.keys(tally)
  .map((sig) => ({ signature: sig, occurrences: tally[sig] }))
  .sort((a, b) => b.occurrences - a.occurrences);

// The per-run budget covers log text only, so the run headers and separators
// push the assembled block a little over. Trim the whole thing as a last step
// - the ceiling has to hold for the assembled block, not just its parts.
let evidence_block = blocks.join('\n\n');
if (evidence_block.length > CHAR_BUDGET) {
  evidence_block = evidence_block.slice(0, CHAR_BUDGET - 40) + '\n... [truncated to fit the token budget]';
  anyClipped = true;
}
const total = runs.length;

return [{
  json: {
    test_name: testName,
    source,
    runs_analyzed: total,
    failed_runs: failing.length,
    passed_runs: passing.length,
    unknown_runs: unknown.length,
    flakiness_rate: total ? Math.round((failing.length / total) * 1000) / 10 : 0,
    run_ids: runs.map((r) => r.run_id),
    failing_run_ids: failing.map((r) => r.run_id),
    signature_tally,
    evidence_block,
    evidence_chars: evidence_block.length,
    truncated: anyClipped,
    evidence_completeness: anyClipped ? 'Partial' : 'Complete',
    // Guard rail 1 lives here as a fact, and is enforced again after the model.
    insufficient_runs: failing.length < 2,
    no_runs: total === 0,
  },
}];

parameters.text:
=TEST: {{ $json.test_name }}

COUNTS - already computed, do not recompute or contradict:
  Runs analysed: {{ $json.runs_analyzed }}
  Failed: {{ $json.failed_runs }}
  Passed: {{ $json.passed_runs }}
  Flakiness rate: {{ $json.flakiness_rate }}%
  Evidence completeness: {{ $json.evidence_completeness }}

FAILURE SIGNATURES - the first signal line of each failing run, grouped:
{{ JSON.stringify($json.signature_tally, null, 1) }}

LOG EXCERPTS FROM THE FAILING RUNS:
{{ $json.evidence_block }}

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "dominant_pattern",
    "pattern_frequency",
    "category",
    "evidence",
    "suspected_cause",
    "fix_suggestion",
    "fix_type",
    "recommendation",
    "confidence",
    "missing_information"
  ],
  "properties": {
    "dominant_pattern": {
      "type": "string",
      "description": "The pattern behind the intermittency, e.g. \"Network Timeout\". Use \"No Dominant Pattern\" when the failures do not resemble each other, or \"Insufficient Runs\" when fewer than two runs failed."
    },
    "pattern_frequency": {
      "type": "number",
      "description": "How many of the failing runs show this pattern. Never more than the failure count supplied."
    },
    "category": {
      "type": "string",
      "enum": [
        "Timing and Race Condition",
        "Network or Timeout",
        "Test Data and State",
        "Environment and Infrastructure",
        "Selector or Locator",
        "Test Ordering and Shared State",
        "Resource Exhaustion",
        "External Dependency",
        "Assertion Tolerance",
        "Unable to Determine"
      ]
    },
    "evidence": {
      "type": "array",
      "description": "Verbatim lines copied from the supplied logs. Quotations are checked against the input.",
      "items": {
        "type": "object",
        "required": [
          "run_id",
          "quoted_line"
        ],
        "properties": {
          "run_id": {
            "type": "string"
          },
          "quoted_line": {
            "type": "string"
          }
        }
      }
    },
    "suspected_cause": {
      "type": "string",
      "description": "Why this pattern produces intermittency rather than a constant failure."
    },
    "fix_suggestion": {
      "type": "string",
      "description": "One concrete action, specific enough to start on. \"Not Provided\" if the evidence does not support one."
    },
    "fix_type": {
      "type": "string",
      "enum": [
        "Test Fix",
        "Product Fix",
        "Infrastructure Fix",
        "Unable to Determine"
      ]
    },
    "recommendation": {
      "type": "string",
      "enum": [
        "Fix Now",
        "Quarantine",
        "Monitor",
        "Not Flaky"
      ]
    },
    "confidence": {
      "type": "string",
      "enum": [
        "High",
        "Medium",
        "Low"
      ]
    },
    "missing_information": {
      "type": "string",
      "description": "What to collect to raise confidence. \"None\" if nothing."
    }
  }
}

parameters.jsCode:
// Last line of defence before anything leaves the workflow.
//
// The structured output parser already shapes the model's answer, so this node
// is not here to parse - it is here to disbelieve. Three things it checks that
// a schema cannot:
//   1. Every quoted line must actually occur in the evidence that was sent.
//      A fabricated quotation is the one failure that would make this tool
//      worse than useless, because an SDET would act on it.
//   2. The counts come from the Budget node, not the model. Flakiness is a
//      frequency claim and models miscount.
//   3. One failing run is never a pattern, however confident the answer reads.

const ctx = $('Budget The Evidence').first().json;
const incoming = $input.first().json;
const model = (incoming && incoming.output) || incoming || {};

const CATEGORIES = [
  'Timing and Race Condition',
  'Network or Timeout',
  'Test Data and State',
  'Environment and Infrastructure',
  'Selector or Locator',
  'Test Ordering and Shared State',
  'Resource Exhaustion',
  'External Dependency',
  'Assertion Tolerance',
  'Unable to Determine',
];
const FIX_TYPES = ['Test Fix', 'Product Fix', 'Infrastructure Fix', 'Unable to Determine'];
const RECOMMENDATIONS = ['Fix Now', 'Quarantine', 'Monitor', 'Not Flaky'];
const CONFIDENCES = ['High', 'Medium', 'Low'];

const str = (v, fallback) => {
  if (v === undefined || v === null) return fallback;
  const s = String(v).trim();
  return s === '' ? fallback : s;
};
const oneOf = (v, allowed, fallback) => {
  const s = str(v, '');
  const hit = allowed.find((a) => a.toLowerCase() === s.toLowerCase());
  return hit || fallback;
};

// Normalise whitespace so a quote is not rejected over indentation alone.
const flat = (s) => String(s).replace(/\s+/g, ' ').trim().toLowerCase();
const haystack = flat(ctx.evidence_block || '');

const notes = [];

// --- evidence: keep only quotes that are really in the logs -----------------
let evidence = Array.isArray(model.evidence) ? model.evidence : [];
const before = evidence.length;
evidence = evidence
  .map((e) => ({
    run_id: str(e && e.run_id, 'Not Provided'),
    quoted_line: str(e && e.quoted_line, ''),
  }))
  .filter((e) => e.quoted_line && haystack.includes(flat(e.quoted_line)));
const dropped = before - evidence.length;
if (dropped > 0) notes.push(dropped + ' quoted line(s) were not found in the supplied logs and were removed');

// --- the counts are ours, not the model's ----------------------------------
const failed = Number(ctx.failed_runs) || 0;
let frequency = Number(model.pattern_frequency);
if (!Number.isFinite(frequency) || frequency < 0) frequency = 0;
if (frequency > failed) {
  notes.push('pattern_frequency was reported as ' + frequency + ' but only ' + failed + ' runs failed; clamped');
  frequency = failed;
}

let pattern = str(model.dominant_pattern, 'Unable to Determine');
let confidence = oneOf(model.confidence, CONFIDENCES, 'Low');
let recommendation = oneOf(model.recommendation, RECOMMENDATIONS, 'Monitor');

// --- guard rails ------------------------------------------------------------
if (ctx.no_runs) {
  pattern = 'No Runs Supplied';
  confidence = 'Low';
  recommendation = 'Monitor';
  notes.push('No runs were supplied, so no analysis was possible');
} else if (ctx.insufficient_runs) {
  // One failure is a stack trace, not a pattern.
  pattern = 'Insufficient Runs';
  confidence = 'Low';
  recommendation = 'Monitor';
  notes.push('Fewer than two failing runs were supplied, so no pattern can be claimed');
}

if (!ctx.insufficient_runs && !ctx.no_runs && evidence.length === 0 && pattern !== 'No Dominant Pattern') {
  confidence = 'Low';
  notes.push('No verifiable quoted evidence survived checking, so confidence was lowered');
}

if (ctx.truncated && confidence === 'High') {
  confidence = 'Medium';
  notes.push('Evidence was truncated to fit the token budget, so confidence was capped at Medium');
}

const analysis = {
  test_name: str(ctx.test_name, 'Unnamed test'),
  runs_analyzed: Number(ctx.runs_analyzed) || 0,
  failed_runs: failed,
  passed_runs: Number(ctx.passed_runs) || 0,
  flakiness_rate: Number(ctx.flakiness_rate) || 0,
  dominant_pattern: pattern,
  pattern_frequency: frequency,
  category: oneOf(model.category, CATEGORIES, 'Unable to Determine'),
  evidence,
  failure_signatures: Array.isArray(ctx.signature_tally) ? ctx.signature_tally : [],
  suspected_cause: str(model.suspected_cause, 'Unable to Determine'),
  fix_suggestion: str(model.fix_suggestion, 'Not Provided'),
  fix_type: oneOf(model.fix_type, FIX_TYPES, 'Unable to Determine'),
  recommendation,
  confidence,
  missing_information: str(model.missing_information, 'None'),
  evidence_completeness: str(ctx.evidence_completeness, 'Unknown'),
  validation_notes: notes.length ? notes : ['No corrections were needed'],
};

// --- message bodies ---------------------------------------------------------
const icon = { 'Fix Now': ':rotating_light:', Quarantine: ':warning:', Monitor: ':eyes:', 'Not Flaky': ':white_check_mark:' }[analysis.recommendation] || ':mag:';

const quoteLines = analysis.evidence
  .slice(0, 4)
  .map((e) => '> `' + e.run_id + '` ' + e.quoted_line)
  .join('\n');

const slack_text = [
  icon + ' *Flaky test RCA — ' + analysis.test_name + '*',
  '',
  '*Pattern:* ' + analysis.dominant_pattern +
    (analysis.pattern_frequency ? '  (' + analysis.pattern_frequency + ' of ' + analysis.failed_runs + ' failures)' : ''),
  '*Category:* ' + analysis.category + '   *Confidence:* ' + analysis.confidence,
  '*Flakiness:* ' + analysis.flakiness_rate + '%  (' + analysis.failed_runs + ' failed / ' + analysis.runs_analyzed + ' runs)',
  '',
  quoteLines ? '*Evidence*\n' + quoteLines : '*Evidence*\n> none that could be verified against the logs',
  '',
  '*Suspected cause:* ' + analysis.suspected_cause,
  '*Suggested fix (' + analysis.fix_type + '):* ' + analysis.fix_suggestion,
  '*Recommendation:* ' + analysis.recommendation,
  '',
  '_Missing information: ' + analysis.missing_information + '_',
].join('\n');

// Telegram renders a different flavour of markdown, so send it plain.
const telegram_text = slack_text
  .replace(/:[a-z_]+:/g, '')
  .replace(/[*`>]/g, '')
  .replace(/_/g, '')
  .trim();

return [{ json: { ...analysis, slack_text, telegram_text } }];
